@-moz-document domain("genius.com") {
/*! FONT Family-Default */
:host, :root {
  --emj: 'Segoe UI Emoji','Segoe UI Symbol';
  --fb0: 'Noto Sans', Vazirmatn, Samim, 'Noto Sans Arabic UI', IranSansWeb, 'Segoe UI', var(--emj);
  --fb1: 'Google Sans Text','Google Sans',Arial;
  --fb2: system,'-apple-system',system-ui,BlinkMacSystemFont,'Helvetica Neue',Helvetica,Arial,'Lucida Grande','Kohinoor Devanagari';
  --fhd: 'Eras ITC', Raleway, 'Noto Sans', Vazirmatn, Samim, 'Noto Sans Arabic UI', IranSans, 'Segoe UI', var(--emj);
  --fh2: 'Noto Sans', Vazirmatn, Samim, 'Noto Sans Arabic UI', IranSans, 'Segoe UI', var(--emj);
  --fmn: 'Cascadia Mono', 'Noto Sans Mono', 'Noto Mono', 'Roboto Mono', 'Dejavu Sans Mono', Menlo, Consolas, 'Courier New';
  --fvn: lining-nums;
  --fbd: var(--fb0), var(--fb1), var(--fb2);
}

html, body {font-family: var(--fbd), sans-serif;}
html, body {font-variant-numeric: var(--fvn);}
textarea, input, button, option, select {font-family: var(--fbd), sans-serif;}
textarea, input, button, option, select {font-variant-numeric: var(--fvn);}
h1, h2, h3 {font-family: var(--fhd), sans-serif;}
h4, h5, h6 {font-family: var(--fh2), sans-serif;}
pre, code, tt, kbd {font-family: var(--fmn), monospace;}
}

@-moz-document domain("genius.com") {
/*! SCRN DIR */
div[class*="Lyrics__Container-sc-"] > p {
  text-align: start;
  unicode-bidi: plaintext;
  line-height: normal;
  line-height: calc(1.125rem * 2);
  font-weight: 300;
  font-family: 'Noto Sans', Vazirmatn;
}
}

@-moz-document domain("genius.com") {
/*! SCRN Footer */
.PageFooter-desktop__Row-sc-caae588f-8 .PageFooter-desktop__FlexWrap-sc-caae588f-9, .jexxBk .iNarWo {
  display: flex;
  flex: 1 0 0%;
  width: 100%;
  height: 100%;
}

.PageFooter-desktop__Row-sc-caae588f-8 .PageFooter-desktop__FlexWrap-sc-caae588f-9 .eEzUlB, .jexxBk .iNarWo .eEzUlB {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 2ch;
  min-width: 2ch;
  text-align: center;
}
}

@-moz-document domain("genius.com") {
/*! EFCT Footer */
.PageFooter-desktop__Row-sc-caae588f-8 a span, .jexxBk a span {
  outline: solid 2px #FFF0;
  outline-offset: -10px;
  transition: 0.25s;
}

.PageFooter-desktop__Row-sc-caae588f-8 a:hover span, .jexxBk a:hover span {
  outline-color: #FFF;
  outline-offset: 5px;
}

.PageFooter-desktop__Row-sc-caae588f-8 .PageFooter-desktop__FlexWrap-sc-caae588f-9 .eEzUlB, .jexxBk .iNarWo .eEzUlB {
  outline: solid 2px #FFF0;
  outline-offset: -10px;
  transition: 0.25s;
}

.PageFooter-desktop__Row-sc-caae588f-8 .PageFooter-desktop__FlexWrap-sc-caae588f-9 .eEzUlB:hover, .jexxBk .iNarWo .eEzUlB:hover {
  outline-color: #FFF;
  outline-offset: 5px;
}

.PageFooter-desktop__Row-sc-caae588f-8 .PageFooter-desktop__FlexWrap-sc-caae588f-9 .eEzUlB span, .jexxBk .iNarWo .eEzUlB span {
  outline: solid 0px #FFF0;
  outline-offset: -00px;
  transition: 0s;
}
}

@-moz-document domain("genius.com") {
/*! FONT Forum */
.forum_post_unit .body li,
.forum_post_unit .body p,
.forum_post_unit .body span,
.forum_post_unit:first-child .body li,
.forum_post_unit:first-child .body p {
  font: normal 15px/160% Programme, var(--fbd), sans-serif;
  unicode-bidi: plaintext;
  text-align: start;
}

h1, h2 {
  font-family: DinCondensed, var(--fbd), sans-serif;
  unicode-bidi: plaintext;
  text-align: start;
}

.discussion_summary h1 {
  font-family: Programme, var(--fbd), sans-serif;
  unicode-bidi: plaintext;
  text-align: start;
}

.artist_tooltip, .follower_unit, .user_tooltip, .user_tooltip .about_me {
  font-family: Programme, var(--fbd), sans-serif;
  unicode-bidi: plaintext;
  text-align: start;
}

.mecha--deprecated textarea {
  font-family: var(--fmn), Consolas,Monaco,Lucida Console,Liberation Mono,DejaVu Sans Mono,Bitstream Vera Sans Mono,Courier New, monospace;
  unicode-bidi: plaintext;
  text-align: start;
}
}

@-moz-document domain("genius.com") {
/*! EFCT Forum hdr Menu */
a.nav_menu-link {
  box-shadow: 0 0;
  transition: box-shadow 0.25s;
}

a.nav_menu-link:hover {
  box-shadow: 0 0.375rem #FF1464;
}
}
